import type { MessageKey } from '@/i18n'

/**
 * Temu — the companion model (see docs/ART_BIBLE.md).
 *
 * A stage is a row of numbers, not a drawing. One SVG reads these and renders
 * every stage, which is what keeps fifteen stages plus five lineages from
 * becoming thousands of hand-drawn frames.
 *
 * Nothing here decides how Temu *looks* emotionally — that is the component.
 * This file only answers "how grown is it, and what unlocks next".
 */

export type Lineage = 'awal' | 'rimbun' | 'pendar' | 'arus' | 'karsa' | 'teduh'

export const LINEAGES: readonly Exclude<Lineage, 'awal'>[] = [
  'rimbun',
  'pendar',
  'arus',
  'karsa',
  'teduh',
]

/** Geometry for one stage. All lengths are fractions of the 200-unit canvas. */
export interface StageShape {
  /** Body height. Everything else is proportional to this. */
  bodyH: number
  /** Body width as a fraction of height. */
  bodyW: number
  /** Degrees. Temu always leans; upright reads as inert. */
  lean: number
  /** Crest height — the part that grows most across a decade. */
  crest: number
  /** How wide the crest fan opens at its tips. */
  crestSpread: number
  /**
   * How many fronds the crest splits into.
   *
   * This is what makes the stages actually different. Before, every dimension
   * grew together, so `kecil` and `abadi` were the same drawing at two sizes —
   * which is exactly what they looked like. Frond count changes the silhouette
   * itself, so the stages read apart at thumbnail size.
   */
  fronds: number
  arm: number
  leg: number
  /** Vertical centre of the face plate, 0 = top of body, 1 = bottom. */
  faceY: number
  /** Face plate width as a fraction of body width. Big — this is the cute part. */
  facePlate: number
  /** Soft aura opacity, 0 until late stages. */
  glow: number
  /** Motes orbiting the body — memories, from stage 11. */
  motes: number
  /** Roots at the base, from stage 12. */
  roots: boolean
}

export interface Stage {
  index: number
  id: string
  name: MessageKey
  blurb: MessageKey
  /** Pair-days needed. Both partners must have shown up on each of them. */
  pairDays: number
  /** Calendar days since pairing. Prevents grinding a decade in a month. */
  relationshipDays: number
  shape: StageShape
}

