export type Eyes = 'dot' | 'arc' | 'sparkle' | 'wide' | 'sleepy' | 'worried' | 'side'
export type Mouth = 'smile' | 'open' | 'o' | 'flat' | 'wavy' | 'pout' | 'laugh'
export type Blush = 'none' | 'dot' | 'soft'

export interface Expression {
  eyes: Eyes
  mouth: Mouth
  blush: Blush
}

export type Mood =
  | 'calm'
  | 'happy'
  | 'celebrate'
  | 'waiting'
  | 'sleepy'
  | 'curious'
  | 'shy'
  | 'proud'
  | 'concerned'

/** Named faces, so a screen asks for a mood and never for eyebrow coordinates. */
export const EXPRESSIONS: Record<Mood, Expression> = {
  calm: { eyes: 'dot', mouth: 'smile', blush: 'none' },
  happy: { eyes: 'dot', mouth: 'open', blush: 'dot' },
  celebrate: { eyes: 'sparkle', mouth: 'laugh', blush: 'soft' },
  waiting: { eyes: 'side', mouth: 'smile', blush: 'none' },
  sleepy: { eyes: 'sleepy', mouth: 'flat', blush: 'none' },
  curious: { eyes: 'wide', mouth: 'o', blush: 'none' },
  shy: { eyes: 'arc', mouth: 'pout', blush: 'soft' },
  proud: { eyes: 'arc', mouth: 'laugh', blush: 'dot' },
  // Used when the app is being gentle — never to blame anyone.
  concerned: { eyes: 'worried', mouth: 'wavy', blush: 'none' },
}

function lerp(a: number, b: number, t: number) {
  return a + (b - a) * t
}
function clamp01(n: number) {
  return Math.max(0, Math.min(1, n))
}
