import { useId, useMemo } from 'react'
import {
  EXPRESSIONS,
  PALETTES,
  shapeFor,
  type Blush,
  type Eyes,
  type Growth,
  type Lineage,
  type Mood,
  type Mouth,
  type StageShape,
} from './model'
import './temu.css'

/**
 * Temu — one parametric SVG for every stage (docs/ART_BIBLE.md).
 *
 * The crest is the identity: two arcs rising from opposite sides that cross at
 * a single point. Below the crossing they are two things; above it, one shape.
 * Everything else — body, face, limbs — is proportional to `bodyH`, so adding a
 * stage means adding a row of numbers, never drawing a new character.
 */

const CANVAS = 200
/**
 * Cheeks are always warm rose, whatever the lineage.
 *
 * They used to take the palette's `accent`, which is a *contrast* colour — on
 * teduh that is teal, so the shy face came out with two green-blue streaks
 * under the eyes and read as crying rather than blushing.
 */
const BLUSH = '#F2708C'
/** Ground anchor. Identical in every stage and frame, which is what stops jitter. */
const GROUND_Y = 172

export interface TemuProps {
  growth: Growth
  lineage?: Lineage
  mood?: Mood
  size?: number
  /** Both halves of the day's pulse — drives the chest mark, not the face. */
  pulse?: { a: boolean; b: boolean }
  /** Big one-shot animation for a milestone. */
  celebrate?: boolean
  className?: string
  /** Screen-reader name. Omit inside a card that already names it. */
  label?: string
}

export function Temu({
  growth,
  lineage = 'awal',
  mood = 'calm',
  size = 200,
  pulse,
  celebrate = false,
  className,
  label,
}: TemuProps) {
  const uid = useId().replace(/:/g, '')
  const s = useMemo(() => shapeFor(growth), [growth])
  const p = PALETTES[lineage]
  const face = EXPRESSIONS[mood]

  // Geometry, all derived from bodyH so proportions hold at every stage.
  const h = s.bodyH
  const w = h * s.bodyW
  const cx = CANVAS / 2
  const bottom = GROUND_Y - s.leg
  const top = bottom - h
  const cy = top + h / 2

  // The reference set's charm comes from a large light plate carrying small
  // features. Everything on the face is sized to the plate, not to the body.
  const faceCy = top + h * s.faceY
  const faceRx = (w * s.facePlate) / 2
  const faceRy = faceRx * 0.94
  const eyeR = Math.max(1.7, faceRx * 0.155)
  const eyeDx = faceRx * 0.42
  const eyeCy = faceCy - faceRy * 0.12
  const mouthCy = faceCy + faceRy * 0.34

  const isSpark = growth.stage.index === 0

  /**
   * Fit the whole figure inside the canvas, anchored to the ground.
   *
   * The late stages used to draw their crest above y=0 — `abadi` reached −24 —
   * so the fan was cut off and every big stage looked like the same body with a
   * bump on top. Clamping here instead of shrinking the numbers keeps growth
   * monotonic (small stages are untouched) and means a future stage can never
   * silently lose its head.
   */
  const figH = s.leg + h + Math.max(0, s.crest - h * 0.05)
  const fit = Math.min(1, (GROUND_Y - 12) / figH)

  return (
    <svg
      className={['temu', celebrate ? 'temu--celebrate' : '', className].filter(Boolean).join(' ')}
      width={size}
      height={size}
      viewBox={`0 0 ${CANVAS} ${CANVAS}`}
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      style={{ overflow: 'visible' }}
    >
      <defs>
        {/* Art bible §3: light always from upper-left, 200°, five stops max. */}
        <linearGradient id={`${uid}-body`} x1="18%" y1="0%" x2="82%" y2="100%">
          <stop offset="0%" stopColor={p.highlight} />
          <stop offset="55%" stopColor={p.body} />
          <stop offset="100%" stopColor={p.deep} />
        </linearGradient>
        <linearGradient id={`${uid}-crest`} x1="0%" y1="100%" x2="100%" y2="0%">
          <stop offset="0%" stopColor={p.body} />
          <stop offset="100%" stopColor={p.highlight} />
        </linearGradient>
        <radialGradient id={`${uid}-glow`}>
          <stop offset="0%" stopColor={p.body} stopOpacity="0.55" />
          <stop offset="70%" stopColor={p.body} stopOpacity="0.12" />
          <stop offset="100%" stopColor={p.body} stopOpacity="0" />
        </radialGradient>
      </defs>

      {/* Aura — late stages only, and never bright enough to compete with the face. */}
      {s.glow > 0.12 && (
        <circle
          className="temu__glow"
          cx={cx}
          cy={cy}
          r={w * 1.15}
          fill={`url(#${uid}-glow)`}
          opacity={s.glow}
        />
      )}

      <ellipse
        className="temu__shadow"
        cx={cx}
        cy={GROUND_Y + 5}
        rx={w * 0.36}
        ry={h * 0.05}
        fill={p.deep}
        opacity="0.16"
      />

      <g transform={`translate(${cx} ${GROUND_Y}) scale(${fit}) translate(${-cx} ${-GROUND_Y})`}>
      {isSpark ? (
        <Spark cx={cx} cy={cy} palette={p} />
      ) : (
        <>
          {s.roots && <Roots cx={cx} y={bottom} w={w} colour={p.deep} />}

          {/* The whole body leans and breathes as one group, so nothing drifts. */}
          <g
            className="temu__body"
            style={{ transformOrigin: `${cx}px ${GROUND_Y}px`, transform: `rotate(${s.lean}deg)` }}
          >
            {s.leg > 0 && <Legs cx={cx} top={bottom} len={s.leg} w={w} colour={p.deep} />}

            <Crest
              cx={cx}
              baseY={top + h * 0.05}
              height={s.crest}
              spread={s.crestSpread}
              fronds={s.fronds}
              fill={`url(#${uid}-crest)`}
              tip={p.highlight}
            />

            {/* Asymmetric bean. The right side carries more mass, which is what
                makes the silhouette read as leaning rather than as an egg. */}
            <path d={beanPath(cx, top, w, h)} fill={`url(#${uid}-body)`} />

            {s.arm > 0 && <Arms cx={cx} cy={cy + h * 0.06} w={w} len={s.arm} colour={p.deep} />}

            {faceRx > 2 && (
              <ellipse cx={cx} cy={faceCy} rx={faceRx} ry={faceRy} fill={p.face} opacity="0.96" />
            )}

            <g className="temu__face">
              <EyePair shape={face.eyes} cx={cx} cy={eyeCy} dx={eyeDx} r={eyeR} accent={p.deep} />
              <MouthShape shape={face.mouth} cx={cx} cy={mouthCy} scale={faceRx * 0.3} accent={p.deep} />
              <BlushPair
                shape={face.blush}
                cx={cx}
                cy={eyeCy + faceRy * 0.3}
                dx={faceRx * 0.68}
                r={eyeR}
                colour={BLUSH}
              />
            </g>

            {pulse && faceRx > 2 && (
              <PulseMark cx={cx} cy={faceCy + faceRy + h * 0.06} r={h * 0.06} pulse={pulse} colour={p.accent} />
            )}

          </g>

          {s.motes > 0 && <Motes cx={cx} cy={cy} r={w * 0.82} count={s.motes} colour={p.accent} />}
        </>
      )}
      </g>
    </svg>
  )
}

/**
 * The bean. Heavier on the right, flat-ish at the base so it sits rather than
 * floats. Hand-tuned control points — the whole brand rests on this silhouette.
 */
function beanPath(cx: number, top: number, w: number, h: number): string {
  const hw = w / 2
  const l = cx - hw
  const r = cx + hw
  const bottom = top + h
  return [
    `M ${cx} ${top}`,
    // upper right — the fuller shoulder
    `C ${cx + hw * 0.72} ${top}, ${r} ${top + h * 0.2}, ${r} ${top + h * 0.5}`,
    // lower right, tucking under
    `C ${r} ${top + h * 0.82}, ${cx + hw * 0.66} ${bottom}, ${cx} ${bottom}`,
    // lower left, slightly tighter so the base is not symmetric
    `C ${cx - hw * 0.62} ${bottom}, ${l} ${top + h * 0.84}, ${l} ${top + h * 0.52}`,
    // upper left — the narrower shoulder
    `C ${l} ${top + h * 0.22}, ${cx - hw * 0.68} ${top}, ${cx} ${top}`,
    'Z',
  ].join(' ')
}

/**
 * Two arcs from opposite sides that cross once. This is the mark — the reason
 * Temu is recognisable as "two" from the silhouette alone.
 */
/**
 * The mark: two filled petals rising from opposite sides that visibly overlap.
 *
 * The first version drew these as thin strokes and it read as rabbit ears —
 * the crossing was invisible, which is the entire point of the shape. Filled
 * teardrops with a real overlap region read as "two things meeting" even at
 * 48 px.
 */
function Crest({
  cx,
  baseY,
  height,
  spread,
  fronds,
  fill,
  tip,
}: {
  cx: number
  baseY: number
  height: number
  spread: number
  /** How many fronds to fan out. 2 keeps the original crossing pair. */
  fronds: number
  fill: string
  tip: string
}) {
  if (height <= 1 || fronds <= 0) return null

  /** One symmetric leaf on the centre line, later rotated into place. */
  const leaf = (h: number, fw: number) => [
    `M ${cx} ${baseY}`,
    `C ${cx + fw * 0.62} ${baseY - h * 0.3}, ${cx + fw * 0.44} ${baseY - h * 0.78}, ${cx} ${baseY - h}`,
    `C ${cx - fw * 0.44} ${baseY - h * 0.78}, ${cx - fw * 0.62} ${baseY - h * 0.3}, ${cx} ${baseY}`,
    'Z',
  ].join(' ')

  // The fan opens wider with every extra frond, and the outer ones are shorter,
  // so the crown has a rounded top instead of reading as a comb.
  const openTo = Math.min(28 + fronds * 9, 86)
  const width = Math.max(4, Math.min(height * 0.5, spread / Math.max(fronds, 1) + height * 0.18))

  return (
    <g className="temu__crest" style={{ transformOrigin: `${cx}px ${baseY}px` }}>
      {Array.from({ length: fronds }, (_, i) => {
        const t = fronds === 1 ? 0 : (i / (fronds - 1)) * 2 - 1 // -1 … 1
        const h = height * (1 - Math.abs(t) * 0.26)
        return (
          <g key={i} transform={`rotate(${(t * openTo) / 2} ${cx} ${baseY})`}>
            <path
              className={i % 2 === 0 ? 'temu__crest-a' : 'temu__crest-b'}
              d={leaf(h, width)}
              fill={fill}
              opacity={Math.abs(t) > 0.6 ? 0.86 : 1}
            />
            {height > 16 && <circle cx={cx} cy={baseY - h} r={Math.max(2, width * 0.22)} fill={tip} />}
          </g>
        )
      })}
    </g>
  )
}

/** Short, thick, rounded. Thin sticks made the earlier version look brittle. */
function Arms({ cx, cy, w, len, colour }: { cx: number; cy: number; w: number; len: number; colour: string }) {
  const width = Math.max(4.2, len * 0.3)
  return (
    <g className="temu__arms" fill="none" stroke={colour} strokeWidth={width} strokeLinecap="round">
      <path className="temu__arm temu__arm--l" d={`M ${cx - w * 0.4} ${cy} q ${-len * 0.5} ${len * 0.16}, ${-len * 0.66} ${len * 0.5}`} />
      <path className="temu__arm temu__arm--r" d={`M ${cx + w * 0.4} ${cy} q ${len * 0.5} ${len * 0.16}, ${len * 0.66} ${len * 0.5}`} />
    </g>
  )
}

function Legs({ cx, top, len, w, colour }: { cx: number; top: number; len: number; w: number; colour: string }) {
  const width = Math.max(4.4, len * 0.46)
  return (
    <g stroke={colour} strokeWidth={width} strokeLinecap="round">
      <line x1={cx - w * 0.17} y1={top - 1} x2={cx - w * 0.19} y2={top + len} />
      <line x1={cx + w * 0.17} y1={top - 1} x2={cx + w * 0.19} y2={top + len} />
    </g>
  )
}

function EyePair({
  shape,
  cx,
  cy,
  dx,
  r,
  accent,
}: {
  shape: Eyes
  cx: number
  cy: number
  dx: number
  r: number
  accent: string
}) {
  // Both eyes always match. Asymmetry at rest reads as a rendering bug.
  const one = (x: number, mirror: number) => {
    switch (shape) {
      case 'arc':
        return <path d={`M ${x - r} ${cy + r * 0.3} q ${r} ${-r * 1.25}, ${r * 2} 0`} fill="none" stroke={accent} strokeWidth={r * 0.62} strokeLinecap="round" />
      case 'sleepy':
        return <path d={`M ${x - r} ${cy} q ${r} ${r * 0.85}, ${r * 2} 0`} fill="none" stroke={accent} strokeWidth={r * 0.6} strokeLinecap="round" />
      case 'worried':
        return <path d={`M ${x - r} ${cy + r * 0.5} q ${r} ${-r * 0.7}, ${r * 2} ${r * 0.1}`} fill="none" stroke={accent} strokeWidth={r * 0.58} strokeLinecap="round" />
      case 'wide':
        return (
          <>
            <ellipse cx={x} cy={cy} rx={r * 1.05} ry={r * 1.3} fill={accent} />
            <circle cx={x + r * 0.3} cy={cy - r * 0.45} r={r * 0.34} fill="#fff" />
          </>
        )
      case 'sparkle':
        return (
          <g>
            <path d={`M ${x} ${cy - r * 1.5} L ${x + r * 0.5} ${cy} L ${x} ${cy + r * 1.5} L ${x - r * 0.5} ${cy} Z`} fill={accent} />
            <path d={`M ${x - r * 1.5} ${cy} L ${x} ${cy - r * 0.5} L ${x + r * 1.5} ${cy} L ${x} ${cy + r * 0.5} Z`} fill={accent} />
          </g>
        )
      case 'side':
        return (
          <>
            <circle cx={x} cy={cy} r={r} fill={accent} />
            <circle cx={x + r * 0.34 * mirror} cy={cy - r * 0.2} r={r * 0.3} fill="#fff" />
          </>
        )
      default:
        return (
          <>
            <circle cx={x} cy={cy} r={r} fill={accent} />
            <circle cx={x + r * 0.3} cy={cy - r * 0.35} r={r * 0.28} fill="#fff" opacity="0.9" />
          </>
        )
    }
  }
  return (
    <g className="temu__eyes" data-eyes={shape} stroke="none">
      {one(cx - dx, 1)}
      {one(cx + dx, 1)}
    </g>
  )
}

function MouthShape({
  shape,
  cx,
  cy,
  scale,
  accent,
}: {
  shape: Mouth
  cx: number
  cy: number
  scale: number
  accent: string
}) {
  const sw = Math.max(1.4, scale * 0.36)
  const stroke = { fill: 'none', stroke: accent, strokeWidth: sw, strokeLinecap: 'round' as const }
  switch (shape) {
    case 'open':
      return <ellipse cx={cx} cy={cy + scale * 0.15} rx={scale * 0.62} ry={scale * 0.72} fill={accent} />
    case 'o':
      return <circle cx={cx} cy={cy + scale * 0.1} r={scale * 0.46} fill={accent} />
    case 'flat':
      return <line x1={cx - scale * 0.46} y1={cy} x2={cx + scale * 0.46} y2={cy} {...stroke} />
    case 'wavy':
      return <path d={`M ${cx - scale * 0.6} ${cy} q ${scale * 0.3} ${-scale * 0.4}, ${scale * 0.6} 0 t ${scale * 0.6} 0`} {...stroke} />
    case 'pout':
      return <path d={`M ${cx - scale * 0.34} ${cy + scale * 0.2} q ${scale * 0.34} ${-scale * 0.42}, ${scale * 0.68} 0`} {...stroke} />
    case 'laugh':
      return (
        <>
          <path d={`M ${cx - scale * 0.72} ${cy - scale * 0.1} a ${scale * 0.72} ${scale * 0.72} 0 0 0 ${scale * 1.44} 0 Z`} fill={accent} />
          <path d={`M ${cx - scale * 0.4} ${cy + scale * 0.42} q ${scale * 0.4} ${scale * 0.3}, ${scale * 0.8} 0`} fill={accent} opacity="0.85" />
        </>
      )
    default:
      return <path d={`M ${cx - scale * 0.5} ${cy - scale * 0.12} q ${scale * 0.5} ${scale * 0.6}, ${scale} 0`} {...stroke} />
  }
}

function BlushPair({
  shape,
  cx,
  cy,
  dx,
  r,
  colour,
}: {
  shape: Blush
  cx: number
  cy: number
  dx: number
  r: number
  colour: string
}) {
  if (shape === 'none') return null
  const o = shape === 'soft' ? 0.5 : 0.34
  const rr = shape === 'soft' ? r * 1.5 : r * 0.85
  return (
    <g fill={colour} opacity={o}>
      <ellipse cx={cx - dx} cy={cy} rx={rr} ry={rr * 0.68} />
      <ellipse cx={cx + dx} cy={cy} rx={rr} ry={rr * 0.68} />
    </g>
  )
}

/**
 * The day's pulse, worn on the chest. Two halves: one per partner.
 * Deliberately not on the face — Temu's mood never depends on whether someone
 * has done their part yet.
 */
function PulseMark({
  cx,
  cy,
  r,
  pulse,
  colour,
}: {
  cx: number
  cy: number
  r: number
  pulse: { a: boolean; b: boolean }
  colour: string
}) {
  const both = pulse.a && pulse.b
  return (
    <g className={`temu__pulse ${both ? 'temu__pulse--full' : ''}`}>
      <circle cx={cx} cy={cy} r={r} fill="#fff" opacity="0.28" />
      <path
        d={`M ${cx} ${cy - r} a ${r} ${r} 0 0 0 0 ${r * 2} Z`}
        fill={colour}
        opacity={pulse.a ? 0.95 : 0.16}
      />
      <path
        d={`M ${cx} ${cy - r} a ${r} ${r} 0 0 1 0 ${r * 2} Z`}
        fill={colour}
        opacity={pulse.b ? 0.95 : 0.16}
      />
    </g>
  )
}

/** One ring per year past the tenth stage. Growth that costs no new art. */

/** Memories in orbit, from the eleventh stage. */
function Motes({ cx, cy, r, count, colour }: { cx: number; cy: number; r: number; count: number; colour: string }) {
  return (
    <g className="temu__motes" style={{ transformOrigin: `${cx}px ${cy}px` }}>
      {Array.from({ length: count }, (_, i) => {
        const angle = (i / count) * Math.PI * 2
        return (
          <circle
            key={i}
            cx={cx + Math.cos(angle) * r}
            cy={cy + Math.sin(angle) * r * 0.42}
            r={2.6}
            fill={colour}
            opacity="0.8"
          />
        )
      })}
    </g>
  )
}

function Roots({ cx, y, w, colour }: { cx: number; y: number; w: number; colour: string }) {
  return (
    <g stroke={colour} strokeWidth="2.2" strokeLinecap="round" opacity="0.5" fill="none">
      <path d={`M ${cx - w * 0.2} ${y} q ${-w * 0.22} ${w * 0.1}, ${-w * 0.34} ${w * 0.05}`} />
      <path d={`M ${cx + w * 0.2} ${y} q ${w * 0.22} ${w * 0.1}, ${w * 0.34} ${w * 0.05}`} />
      <path d={`M ${cx} ${y} q ${-w * 0.05} ${w * 0.14}, ${-w * 0.14} ${w * 0.18}`} />
    </g>
  )
}

/** Stage 0 — before there is a body, there are just two sparks finding each other. */
function Spark({ cx, cy, palette }: { cx: number; cy: number; palette: { body: string; accent: string } }) {
  return (
    <g className="temu__spark">
      <circle className="temu__spark-a" cx={cx - 14} cy={cy} r="7" fill={palette.body} />
      <circle className="temu__spark-b" cx={cx + 14} cy={cy} r="7" fill={palette.accent} />
    </g>
  )
}

export type { StageShape }
